def enhance_html(html: str) -> str:
    html = str(html or "")
    if "</body>" not in html:
        return html
    if _CSS_MARKER not in html and "</head>" in html:
        html = html.replace("</head>", SIMPLE_CSS + "\n</head>", 1)
    if _JS_MARKER not in html:
        html = html.replace("</body>", SIMPLE_JS + "\n</body>", 1)
    return html


def _guard_optional_browser_apis(html: str) -> str:
    """Ne laisse pas une API navigateur optionnelle casser tout le dashboard."""
    anchor = '  const connectLive = () => {\n    const guildId = currentGuild();'
    replacement = '  const connectLive = () => {\n    if (typeof EventSource === "undefined") return;\n    const guildId = currentGuild();'
    if anchor in html and replacement not in html:
        html = html.replace(anchor, replacement, 1)
    return html


def _install_unified_runtime_hook() -> bool:
    try:
        from . import dashboard_unified_runtime_v2 as runtime
    except Exception:
        logger.exception("Mode simple : runtime unified-v2 indisponible.")
        return False
    current = runtime.enhance_html
    if getattr(current, _RUNTIME_HOOK_MARKER, False):
        return True

    def runtime_then_product_then_simple(html: str) -> str:
        rendered = current(html)
        try:
            from .dashboard_product_ui_v18_live_fix import patch_html as patch_product_html
            rendered = patch_product_html(rendered)
        except Exception:
            logger.exception("Composition V18/V19 impossible avant le gel V55.")
        rendered = _guard_optional_browser_apis(rendered)
        return enhance_html(rendered)

    setattr(runtime_then_product_then_simple, _RUNTIME_HOOK_MARKER, True)
    runtime_then_product_then_simple._sentrix_original = current
    runtime.enhance_html = runtime_then_product_then_simple
    return True


def install(dashboard) -> None:
    global _INSTALLED
    _install_unified_runtime_hook()
    html = getattr(dashboard, "INDEX_HTML", "")
    if not isinstance(html, str) or "</body>" not in html:
        logger.warning("Mode simplifié non installé : INDEX_HTML indisponible.")
        return
    enhanced = enhance_html(html)
    if enhanced != html:
        dashboard.INDEX_HTML = enhanced
    if not _INSTALLED:
        _INSTALLED = True
        logger.info("Dashboard simplifié SentriX installé (V18/V19/V20 composés dans V55).")


__all__ = ["SIMPLE_CSS", "SIMPLE_JS", "enhance_html", "install"]
